package application.controller;
import application.model.dao.InsumoDAO;
import application.model.entity.*;
import application.util.Json;
import javafx.scene.web.WebEngine;
import java.util.*;

public class InsumoBridge {
 private static final String FAIL="{\"ok\":false}";
 private final WebEngine engine; private final WebBridge web; private final InsumoDAO dao=new InsumoDAO();
 public InsumoBridge(WebEngine e,WebBridge w){engine=e;web=w;}
 public boolean esAdministrador(){Usuario u=web.usuarioActual();return u!=null&&u.esAdministrador();}
 private boolean permitido(){if(esAdministrador())return true;error("Solo el administrador puede gestionar Insumos");return false;}
 public String insumos(){if(!permitido())return "[]";try{StringBuilder b=new StringBuilder("[");boolean first=true;for(InsumoAdmin i:dao.todos()){if(!first)b.append(',');first=false;b.append("{\"id\":").append(i.id()).append(",\"n\":").append(Json.texto(i.nombre())).append(",\"u\":").append(Json.texto(i.unidad())).append(",\"s\":").append(i.stock()).append(",\"min\":").append(i.minimo()).append(",\"c\":").append(i.costoUnidad()).append(",\"pid\":").append(i.idProveedor()==null?"null":i.idProveedor()).append(",\"prov\":").append(Json.texto(i.proveedor())).append(",\"a\":").append(i.activo()).append(",\"uso\":").append(i.productosUsados()).append('}');}return b.append(']').toString();}catch(Exception e){return fallo(e,"No se pudieron leer los insumos");}}
 public String proveedores(){if(!permitido())return "[]";try{StringBuilder b=new StringBuilder("[");boolean first=true;for(Proveedor p:dao.proveedores()){if(!first)b.append(',');first=false;b.append("{\"id\":").append(p.id()).append(",\"n\":").append(Json.texto(p.nombre())).append(",\"tel\":").append(Json.texto(p.telefono())).append(",\"rtn\":").append(Json.texto(p.rtn())).append(",\"a\":").append(p.activo()).append(",\"uso\":").append(p.insumos()).append('}');}return b.append(']').toString();}catch(Exception e){return fallo(e,"No se pudieron leer los proveedores");}}
 public String historial(String id){if(!permitido())return "[]";try{int n=Integer.parseInt(id);StringBuilder b=new StringBuilder("[");boolean first=true;for(MovimientoInventario m:dao.historial(n)){if(!first)b.append(',');first=false;b.append("{\"f\":").append(Json.texto(m.fecha())).append(",\"t\":").append(Json.texto(m.tipo())).append(",\"q\":").append(m.cantidad()).append(",\"u\":").append(Json.texto(m.unidad())).append(",\"n\":").append(Json.texto(m.nota())).append('}');}return b.append(']').toString();}catch(Exception e){return fallo(e,"No se pudo leer el historial");}}
 public String guardarInsumo(String id,String nombre,String unidad,String minimo,String costo,String proveedor,String activo){if(!permitido())return FAIL;try{String n=nombre==null?"":nombre.trim();if(n.isEmpty()||n.length()>80)throw new IllegalArgumentException("El nombre debe tener entre 1 y 80 caracteres");if(!Set.of("g","ml","ud").contains(unidad))throw new IllegalArgumentException("Elige una unidad válida");int min=entero(minimo),c=entero(costo);if(min<0||c<0)throw new IllegalArgumentException("Stock mínimo y costo no pueden ser negativos");Integer pid=proveedor==null||proveedor.isBlank()?null:entero(proveedor);dao.guardar(id==null||id.isBlank()?null:entero(id),n,unidad,min,c,pid,"1".equals(activo));return "{\"ok\":true}";}catch(Exception e){return fallo(e,"No se pudo guardar el insumo");}}
 public String guardarProveedor(String id,String nombre,String telefono,String rtn,String activo){if(!permitido())return FAIL;try{String n=nombre==null?"":nombre.trim();if(n.isEmpty()||n.length()>80)throw new IllegalArgumentException("Escribe un nombre de proveedor (máximo 80 caracteres)");dao.proveedor(id==null||id.isBlank()?null:entero(id),n,telefono==null?"":telefono.trim(),rtn==null?"":rtn.trim(),"1".equals(activo));return "{\"ok\":true}";}catch(Exception e){return fallo(e,"No se pudo guardar el proveedor");}}
 public String registrarCompra(String id,String cantidadBase,String totalCent,String actualizar,String nota){if(!permitido())return FAIL;try{int q=entero(cantidadBase),total=entero(totalCent);dao.compra(entero(id),q,total,"1".equals(actualizar),nota==null?"Compra":nota.trim());return "{\"ok\":true}";}catch(Exception e){return fallo(e,"No se pudo registrar la compra");}}
 public String ajustarStock(String id,String delta,String nota){if(!permitido())return FAIL;try{String n=nota==null?"":nota.trim();if(n.isEmpty())throw new IllegalArgumentException("Escribe el motivo del ajuste");if(n.length()>160)throw new IllegalArgumentException("El motivo es demasiado largo");dao.ajuste(entero(id),entero(delta),n);return "{\"ok\":true}";}catch(Exception e){return fallo(e,"No se pudo ajustar el stock");}}
 private int entero(String s){return Integer.parseInt(s==null?"":s.trim());}
 private String fallo(Exception e,String gen){if(e instanceof NumberFormatException){error("Revisa los datos numéricos");}else if(e instanceof IllegalArgumentException||e instanceof IllegalStateException){error(e.getMessage());}else{e.printStackTrace();error(gen);}return FAIL;}
 private void error(String s){engine.executeScript("window.mostrarError && window.mostrarError("+Json.texto(s)+")");}
}
